    {contextPending&&!busy&&<p role="status" className="text-xs text-muted-foreground">正在同步编辑器上下文…</p>}{tab.error&&<p role="alert" className="rounded bg-destructive/10 p-2 text-xs text-destructive">{tab.error}</p>}{standalone&&!tab.ready&&<p role="status" className="text-xs text-muted-foreground">正在连接对话…</p>}{notice&&<p className="rounded bg-muted/40 p-2 text-[11px] text-muted-foreground">{notice}</p>}
